const express = require('express');
const { EventStoreDBClient, jsonEvent } = require('@eventstore/db-client');
const { verifyCustomerJwt } = require('../auth');
const { db } = require('../db');

const router = express.Router();
const eventStore = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URI);

router.post('/api/commands/upgrade-plan', verifyCustomerJwt, async (req, res) => {
  const { subscriptionId, newPlanTier, promoCode } = req.body;

  const sub = await db.query(
    'SELECT id FROM customer_subscriptions WHERE id = $1 AND customer_id = $2',
    [subscriptionId, req.customer.id]
  );
  if (!sub.rows.length) {
    return res.status(403).json({ error: 'Forbidden: subscription does not belong to current user' });
  }

  const event = jsonEvent({
    type: 'SubscriptionPlanChanged',
    data: { subscriptionId, newPlanTier, promoCode, changedAt: new Date() }
  });

  await eventStore.appendToStream(`subscription-${subscriptionId}`, [event]);
  res.json({ success: true, subscriptionId, tier: newPlanTier });
});
